(() => {
  const slides = [...document.querySelectorAll('.slide')];
  const nav = document.getElementById('nav');
  let idx = 0;
  slides.forEach((_, i) => {
    const d = document.createElement('div');
    d.className = 'dot' + (i === 0 ? ' on' : '');
    nav.appendChild(d);
  });
  const dots = [...document.querySelectorAll('.dot')];
  function show(next) {
    slides[idx].classList.remove('active');
    dots[idx].classList.remove('on');
    idx = (next + slides.length) % slides.length;
    slides[idx].classList.add('active');
    dots[idx].classList.add('on');
  }
  window.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') show(idx + 1);
    if (e.key === 'ArrowLeft' || e.key === 'PageUp') show(idx - 1);
  });
  let touchStartX = null;
  window.addEventListener('touchstart', (e) => touchStartX = e.changedTouches[0].clientX, {passive:true});
  window.addEventListener('touchend', (e) => {
    if (touchStartX === null) return;
    const dx = e.changedTouches[0].clientX - touchStartX;
    if (dx < -40) show(idx + 1);
    if (dx > 40) show(idx - 1);
    touchStartX = null;
  }, {passive:true});
})();
